// Resolve cut times. 'L<n>' = the beat at or just before line n's first sung word (within 0.45 s; otherwise 0.08 s early),
// so a shot is already up when its line starts. Works in the browser (SONG global) and in node (pass song).
function shotTime(at, song = typeof SONG !== 'undefined' ? SONG : null) {
  if (typeof at === 'number') return at;
  const n = +String(at).slice(1), line = song.lines.find(l => l.i === n), t0 = line.words[0].t0 ?? line.t0;
  let best = null; for (const b of song.beats) if (b <= t0 && t0 - b < .45) best = b;
  return best ?? t0 - .08;
}
if (typeof module !== 'undefined') module.exports = { DGQ_SHOTS, DGQ_FLOWS, DGQ_TWEETS, shotTime };
